(()=>{
 const CSS=`
 .pa-menu10{box-sizing:border-box!important;width:min(1120px,calc(100% - 96px))!important;max-width:1120px!important;margin:clamp(84px,11vh,128px) auto 36px!important;padding:0!important;display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:0 clamp(50px,7vw,108px)!important;align-content:start!important}
 .pa-menu10__item{box-sizing:border-box!important;position:relative!important;display:grid!important;grid-template-columns:34px minmax(0,1fr) 38px!important;align-items:center!important;width:100%!important;min-height:80px!important;margin:0!important;padding:13px 4px 14px 0!important;border:0!important;border-top:1px solid rgba(7,28,30,.2)!important;background:transparent!important;text-decoration:none!important;overflow:hidden!important;transform:none!important;inset:auto!important}
 .pa-menu10__item:nth-child(7),.pa-menu10__item:nth-child(8){border-bottom:1px solid rgba(7,28,30,.2)!important}
 .pa-menu10__no{all:unset!important;box-sizing:border-box!important;grid-column:1!important;display:block!important;color:rgba(7,28,30,.58)!important;font:500 10px/1 'IBM Plex Mono',monospace!important;letter-spacing:.12em!important;writing-mode:horizontal-tb!important;transform:none!important}
 .pa-menu10__label{all:unset!important;box-sizing:border-box!important;grid-column:2!important;display:block!important;min-width:0!important;color:#071c1e!important;font:400 clamp(34px,3vw,54px)/.97 'Cormorant Garamond',Georgia,serif!important;letter-spacing:-.035em!important;white-space:normal!important;word-break:normal!important;overflow:visible!important;cursor:pointer!important}
 .pa-menu10__arrow{all:unset!important;grid-column:3!important;justify-self:end!important;color:#b8643f!important;font:400 20px/1 Arial,sans-serif!important;opacity:0!important;transition:opacity .2s ease!important}
 .pa-menu10__item:hover,.pa-menu10__item:focus-visible{background:rgba(184,100,63,.045)!important;padding-left:8px!important}.pa-menu10__item:hover .pa-menu10__arrow,.pa-menu10__item:focus-visible .pa-menu10__arrow{opacity:1!important}
 .pa-menu10__compass{all:unset!important;box-sizing:border-box!important;grid-column:3!important;justify-self:end!important;display:block!important;position:relative!important;width:30px!important;height:30px!important;border:1px solid #b8643f!important;border-radius:50%!important}
 .pa-menu10__compass:before,.pa-menu10__compass:after{content:''!important;position:absolute!important;border:1px solid rgba(184,100,63,.22)!important;border-radius:50%!important}.pa-menu10__compass:before{inset:6px!important}.pa-menu10__compass:after{inset:11px!important}.pa-menu10__needle{all:unset!important;position:absolute!important;left:50%!important;top:4px!important;width:1px!important;height:22px!important;background:linear-gradient(#b8643f 0 49%,#071c1e 50%)!important;transform:rotate(28deg)!important;animation:pa10needle 5s ease-in-out infinite alternate!important}@keyframes pa10needle{to{transform:rotate(70deg)}}
 @media(max-height:780px) and (min-width:761px){.pa-menu10{margin-top:65px!important}.pa-menu10__item{min-height:65px!important;padding-top:9px!important;padding-bottom:9px!important}.pa-menu10__label{font-size:clamp(29px,2.45vw,44px)!important}}
 @media(max-width:760px){.pa-menu10{width:calc(100% - 34px)!important;max-width:none!important;margin:80px auto 30px!important;grid-template-columns:1fr!important;gap:0!important}.pa-menu10__item{grid-template-columns:29px minmax(0,1fr) 34px!important;min-height:59px!important;padding:9px 1px 10px 0!important}.pa-menu10__item:nth-child(7){border-bottom:0!important}.pa-menu10__no{font-size:9px!important}.pa-menu10__label{font-size:clamp(29px,9vw,42px)!important;line-height:1!important}.pa-menu10__arrow{opacity:.55!important;font-size:16px!important}.pa-menu10__compass{width:27px!important;height:27px!important}}
 `;
 const installStyle=()=>{let s=document.getElementById('pa-menu10-style');if(!s){s=document.createElement('style');s.id='pa-menu10-style';s.textContent=CSS;document.head.appendChild(s)}};
 const run=()=>{
  installStyle();
  const old=document.querySelector('.nav-links,.nav-links-v259,.nav-links-v258');
  if(!old||old.classList.contains('pa-menu10'))return;
  const en=(document.documentElement.lang||'').toLowerCase().startsWith('en')||location.pathname.startsWith('/en/');
  const items=en?[[1,'Profile','#manifesto'],[2,'Research Atlas','#atlas'],[3,'Publications','/en/publications.html'],[4,'Diplomatic Record','#records'],[5,'Ask the Atlas','/en/ask.html'],[6,'Timeline','/timeline.html'],[7,'Contact','#contact'],[8,'Compass','/pusula.html']]:[[1,'Profil','#manifesto'],[2,'Araştırma Atlası','#atlas'],[3,'Yayınlar','/yayinlar.html'],[4,'Diplomatik Kayıt','#records'],[5,'Atlas’a Sor','/ask.html'],[6,'Zaman Çizelgesi','/timeline.html'],[7,'Temas','#contact'],[8,'Pusula','/pusula.html']];
  const menu=document.createElement('div');menu.className='pa-menu10';menu.setAttribute('role','navigation');menu.setAttribute('aria-label',en?'Main menu':'Ana menü');
  items.forEach(([n,label,href])=>{const a=document.createElement('a');a.className='pa-menu10__item';a.href=href;const no=document.createElement('i');no.className='pa-menu10__no';no.textContent=String(n).padStart(2,'0');const tx=document.createElement('b');tx.className='pa-menu10__label';tx.textContent=label;a.append(no,tx);if(n===8){const c=document.createElement('i');c.className='pa-menu10__compass';c.innerHTML='<i class="pa-menu10__needle"></i>';a.append(c)}else{const ar=document.createElement('i');ar.className='pa-menu10__arrow';ar.textContent='↗';a.append(ar)}menu.append(a)});
  old.replaceWith(menu);document.querySelectorAll('.nav-compass-chip,.nav-compass-link,.menu-compass-floating,.nav-compass-eight').forEach(x=>{if(!menu.contains(x))x.remove()});
 };
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run,{once:true});else run();setTimeout(run,250);setTimeout(run,900);
})();
